package uk.ac.ravensbourne.casevault.service;
import static org.junit.jupiter.api.Assertions.*; import java.util.*; import org.junit.jupiter.params.ParameterizedTest; import org.junit.jupiter.params.provider.EnumSource; import uk.ac.ravensbourne.casevault.domain.*; import uk.ac.ravensbourne.casevault.security.UserPrincipal;
class AccessPolicyTest { private final AccessPolicy policy=new AccessPolicy(); private final UUID org=UUID.randomUUID(); private final CaseRecord record=new CaseRecord(UUID.randomUUID(),new Organisation(org,"Tenant"),"t","d",Category.OTHER,Severity.LOW,new UserAccount(UUID.randomUUID(),new Organisation(org,"Tenant 2"),"a@x.test","h",Role.CLIENT_USER)); private UserPrincipal p(Role r,UUID tenant){return new UserPrincipal(UUID.randomUUID(),tenant,"u@test","h",r.name(),true,false);} @ParameterizedTest @EnumSource(Role.class) void tAuthz001RoleViewMatrix(Role role){boolean expected=role==Role.CASE_MANAGER||role==Role.CLIENT_USER||role==Role.SECURITY_ANALYST;assertEquals(expected,policy.canViewCase(p(role,org),record,true));} @ParameterizedTest @EnumSource(Role.class) void tAuthz002UnassignedAnalystAndOtherTenantDenied(Role role){var principal=p(role,UUID.randomUUID());boolean allowed=policy.canViewCase(principal,record,false);assertEquals(role==Role.CASE_MANAGER,allowed);} @org.junit.jupiter.api.Test void tAuthzIdor001ClientOtherTenantDenied(){assertFalse(policy.canViewCase(p(Role.CLIENT_USER,UUID.randomUUID()),record,false));} @org.junit.jupiter.api.Test void tAuthzOwnReport001ManagerCannotApproveOwn(){var manager=p(Role.CASE_MANAGER,org);assertFalse(policy.canApproveReport(manager,record,manager.id()));} }
